#define WASM_RT_SEGUE_WRITE_BASE(base) \
  __builtin_ia32_wrgsbase64((uintptr_t)base)
#define MEM_ADDR_MEMOP(mem, addr, n) ((uint8_t __seg_gs*)(uintptr_t)addr)
#else
#define MEM_ADDR_MEMOP(mem, addr, n) MEM_ADDR(mem, addr, n)
